#include <stdint.h>

#include "main.h"

int main(void)
{
	RCC_AHB1ENR_t volatile *pClockCtrlreg = (RCC_AHB1ENR_t*) 0x40023830;
	GPIOx_MODE_t volatile *pPortAModereg = (GPIOx_MODE_t*) 0x40020000;
	GPIOx_ODR_t volatile *pPortAOutreg = (GPIOx_ODR_t*) 0x40020014;

	pClockCtrlreg->gpioa_en = 1;
	pPortAModereg ->pin_5 = 0;
	pPortAModereg ->pin_5 = 1;

	 while(1)
	   {

		   // SET 5th bit bit of output data register to make I/O pin-5 as HIGH
		   pPortAOutreg ->pin_5 = 1;

		   //introduce small human observable delay
		   //This loop execute for 300k times
		   for(uint32_t i=0 ; i < 300000 ; i++ );
		   for(volatile uint32_t i=0 ; i < 300000 ; i++ );


		   //Turn OFF the LED
		  pPortAOutreg ->pin_5 = 0;

		   for(uint32_t i=0 ; i < 300000 ; i++ );
		   for(volatile uint32_t i=0 ; i < 300000 ; i++ );

	   }





}
